-- ============================================================================
-- PARTIE 21 — Contenu du module 9 « Environnement sain, écrans, extérieur » (3 séquences)
-- Source : Projet pédagogique Koalakids (environnement beau, sain et propice à
-- l'éveil, jeu en extérieur, sorties, tenue adaptée, planification, contact avec
-- la nature, environnement sans trop de restrictions).
-- Le projet pédagogique ne traite pas des écrans : ce volet n'est pas couvert par
-- ce module.
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 21.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Jouer dehors le plus souvent possible : le contact réel avec la nature est essentiel au développement de l'enfant.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire pourquoi l'extérieur et un environnement sain font partie des besoins de l'enfant, et de repérer ce qui permettrait de sortir plus souvent.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Environnement sain et jeu en extérieur"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un moment passé dehors avec les enfants cette semaine, ou à une sortie qui n'a pas eu lieu, sans les raconter."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Dehors, même sous la pluie : l'extérieur fait partie de l'environnement sain dont l'enfant a besoin.", "idees": ["L'enfant a besoin d'évoluer dans un environnement beau, sain et propice à son éveil : soigné, ludique, ouvert et accessible, pour favoriser ses propres choix et ses propres expériences.", "Prendre l'air est conseillé pour limiter les infections respiratoires, même quand il fait froid ou qu'il pleut. Recevoir les sensations liées au climat permet aux enfants d'apprendre leur environnement.", "Avec un jardin, les propositions de jeu peuvent s'y installer selon la météo, portes ouvertes l'été, repas et goûter possibles dehors. Sans espace extérieur, des sorties sont organisées chaque jour (parc, médiathèque, espace culturel…) pour s'aérer, exercer sa motricité et jouer avec le sable ou la terre."], "support": "Projet pédagogique Koalakids, « Les enfants doivent pouvoir jouer en extérieur le plus souvent possible »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un moment vécu cette semaine dehors, ou une sortie qui n'a pas eu lieu, sans nommer d'enfant. On analyse l'organisation, pas la personne.", "questions": ["Que s'est-il passé ? (les faits : météo, tenue, adultes présents)", "Qu'ont vécu ou découvert les enfants dehors ?", "Qu'est-ce qui a facilité ou freiné la sortie ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : proposer une sortie ou un jeu dehors par temps de pluie, avec la bonne tenue.", "Exemple : installer une proposition de jeu dans le jardin.", "Exemple : noter ce qu'un enfant découvre dehors (sable, terre, feuilles)."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 2/3 : analyse de ce qui freine les sorties sur le site."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 9 % 1/3 %';
-- FIN 21.1a

-- ---------------------------------------------------------------------------
-- 21.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Dehors, c'est aussi de l'éveil", "paragraphes": ["Le jeune enfant absorbe le monde avec tous ses sens. Jouer dehors, c'est **recevoir les sensations du climat**, explorer le sable, la terre, les végétaux, et découvrir la nature en la respectant.", "Cette première séance pose un repère : sortir **le plus souvent possible**, même par temps froid ou pluvieux, fait partie de l'environnement sain dont les enfants ont besoin."]}$kk$),
  (1,'citation',$kk${"texte": "« Le contact réel avec la nature est essentiel à mon développement. »\nCharte nationale pour l'accueil du jeune enfant"}$kk$),
  (2,'retenir',$kk${"titre": "À retenir", "points": ["**Un environnement beau, sain et propice à l'éveil :** soigné, ludique, ouvert et accessible.", "**Prendre l'air** limite les infections respiratoires, même quand il fait froid ou qu'il pleut, et fait découvrir les sensations du climat.", "**Jardin ou sorties quotidiennes :** s'aérer, bouger, jouer avec le sable ou la terre."]}$kk$),
  (3,'reflexion',$kk${"question": "Pensez à la dernière fois que vous avez joué dehors avec les enfants. Qu'ont-ils découvert ? Qu'est-ce qui vous a le plus plu ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à mesurer ce que le dehors apporte.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Sortir, trois temps", "etapes": [{"titre": "Préparer la tenue.", "texte": "Surpantalon imperméable, vêtement chaud et imperméable, bottes : tout est prêt avant de sortir."}, {"titre": "Sortir ou installer dehors.", "texte": "Une sortie, ou une proposition de jeu dans le jardin selon la météo."}, {"titre": "Laisser explorer.", "texte": "Sable, terre, feuilles : je mets des mots sur ce que l'enfant découvre."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 9 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 21.1b

-- ---------------------------------------------------------------------------
-- 21.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Qu'est-ce qui nous empêche de sortir ? On regarde les freins de l'organisation, pas les personnes.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de repérer ce qui freine les sorties et le jeu en extérieur sur le site, et de proposer un ajustement de l'organisation pour le lever.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Environnement sain et jeu en extérieur"}, "duree_min": 45, "materiel": ["Paperboard (pour noter les freins et les ajustements)", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Sortir demande une organisation : on planifie, on prévoit la tenue, on garde un adulte sur chaque proposition.", "idees": ["Les propositions de jeu en extérieur et les sorties s'intègrent dans la planification, avec une tenue adaptée : surpantalon imperméable, vêtement chaud et imperméable, bottes.", "La planification garantit la concomitance et la concordance des propositions de jeu, ainsi que la fluidité et la qualité du jeu, et sert de base de communication avec les parents.", "Un professionnel stable et disponible est présent en continu sur chaque proposition de jeu, y compris dehors, pour assurer la sécurité physique et affective des enfants."], "support": "Projet pédagogique Koalakids, « Les enfants doivent pouvoir jouer en extérieur le plus souvent possible »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir la dernière fois que l'on n'a pas sorti les enfants, ou qu'une sortie a été difficile, sans nommer d'enfant. On cherche les freins de l'organisation.", "questions": ["Qu'est-ce qui s'est passé la dernière fois que nous avons (ou n'avons pas) sorti les enfants ?", "Qu'est-ce qui nous a freinés : le temps, la tenue, les adultes, l'organisation ?", "Qu'est-ce qui, dans la planification, pourrait lever ce frein ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : vérifier que les tenues adaptées sont prêtes avant la sortie.", "Exemple : proposer d'inscrire une sortie ou un jeu dehors dans la planification.", "Exemple : rester sur la proposition de jeu dehors, comme adulte stable et disponible."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur l'environnement des enfants."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 9 % 2/3 %';
-- FIN 21.2a

-- ---------------------------------------------------------------------------
-- 21.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Chercher les freins, pas les coupables", "paragraphes": ["Sortir avec de jeunes enfants demande de l'organisation : une tenue, des adultes, une planification. Quand une sortie n'a pas lieu, il y a souvent **un frein concret** que l'on peut lever.", "Cette séance propose d'analyser une situation vécue en regardant l'organisation, jamais les personnes."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Il pleut, on reste dedans", "texte": "Il pleut. L'équipe décide de ne pas sortir : « Ils vont attraper froid. »", "analyse": "prendre l'air est conseillé pour limiter les infections respiratoires, même quand il fait froid ou qu'il pleut. Avec la bonne tenue, la pluie devient une expérience : recevoir les sensations du climat permet d'apprendre son environnement."}, {"lettre": "B", "titre": "On sort sans la tenue adaptée", "texte": "L'équipe sort avec des enfants sans vêtement imperméable ni bottes. Au bout de dix minutes, tout le monde rentre trempé.", "analyse": "les sorties s'intègrent dans la planification, avec une tenue adaptée : surpantalon imperméable, vêtement chaud et imperméable, bottes. La préparer à l'avance évite d'y renoncer."}, {"lettre": "C", "titre": "Le jardin sans adulte", "texte": "Des jeux sont installés dehors, mais les adultes restent à l'intérieur pour préparer le repas.", "analyse": "un professionnel stable et disponible est présent en continu sur chaque proposition de jeu, y compris dehors. C'est la planification qui permet de répartir les adultes."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour sortir plus souvent avec les enfants.", "plutot": ["Sortir même quand il fait froid ou qu'il pleut, avec la tenue adaptée.", "Intégrer les sorties et le jeu dehors dans la planification.", "Garder un professionnel stable et disponible sur chaque proposition.", "Laisser les enfants explorer le sable, la terre et les éléments de la nature."], "eviter": ["Renoncer à sortir à cause du temps.", "Sortir sans tenue adaptée.", "Installer un jeu dehors sans adulte présent.", "Remettre la sortie à plus tard sans la planifier."]}$kk$),
  (3,'reflexion',$kk${"question": "Qu'est-ce qui, sur votre site, rend une sortie compliquée ? Quel petit changement la rendrait plus simple ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Trois questions devant un frein", "etapes": [{"titre": "Quel est le frein ?", "texte": "Le temps, la tenue, les adultes, l'organisation : je le nomme précisément."}, {"titre": "Où peut-on agir ?", "texte": "Dans la planification, la préparation ou la répartition des adultes."}, {"titre": "Qu'est-ce qu'on teste ?", "texte": "Un ajustement simple, pour la semaine qui vient."}], "note": "On analyse l'organisation, jamais les personnes."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 9 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 21.2b

-- ---------------------------------------------------------------------------
-- 21.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Un environnement beau, sain et ouvert s'entretient par petits gestes : on teste et on garde ce qui marche.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée dans l'environnement des enfants (dehors ou dedans), et l'équipe a choisi une pratique commune pour l'entretenir.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Environnement sain et jeu en extérieur"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un environnement sain se prépare : on le soigne, on l'ouvre et on évite d'y multiplier les interdits.", "idees": ["L'environnement est soigné, ludique, ouvert et accessible : le jeune enfant absorbe le monde qui l'entoure avec tous ses sens.", "Les propositions de jeu s'enrichissent des opportunités locales, des talents des parents ou des professionnels et de la présence occasionnelle d'artistes : la crèche reste ouverte sur le monde extérieur.", "Un environnement sans danger et sans trop de restrictions : s'il présente trop d'obstacles ou d'interdits, l'adulte doit intervenir sans cesse, et l'accompagnement se fait sur un mode de limites peu propice aux apprentissages."], "support": "Projet pédagogique Koalakids, « Organiser un environnement ludique sans danger et sans trop de restrictions »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'ont fait les enfants ? Qu'est-ce qui a changé, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 9. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 9 % 3/3 %';
-- FIN 21.3a

-- ---------------------------------------------------------------------------
-- 21.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Un environnement qui s'entretient", "paragraphes": ["Un environnement beau, sain et propice à l'éveil ne se fait pas une fois pour toutes. Il se **soigne**, s'enrichit de ce que la vie locale et les parents apportent, et évite de multiplier les interdits.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour entretenir l'environnement des enfants."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Soigné, ludique, ouvert, accessible :** le jeune enfant absorbe le monde avec tous ses sens.", "**Ouvert sur le monde :** les opportunités locales, les talents des parents ou des professionnels, la présence occasionnelle d'artistes enrichissent les propositions.", "**Peu d'interdits :** trop d'obstacles obligent l'adulte à intervenir sans cesse, au détriment des apprentissages."]}$kk$),
  (2,'reflexion',$kk${"question": "Dans votre espace, qu'est-ce qui oblige le plus souvent à dire « non » aux enfants ? Que pourriez-vous retirer, déplacer ou sécuriser ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche ce qui rendrait l'espace plus libre.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple d'entretien de l'environnement, que chacun fait de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 9 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 21.3b

-- ---------------------------------------------------------------------------
-- 21c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 4.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 9 %/3 %' order by m.ordre;
-- FIN 21c
